import React, { useMemo } from 'react';
import {
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
  random,
  AbsoluteFill,
  Sequence,
} from 'remotion';
import { ThreeCanvas } from '@remotion/three';
import { Edges } from '@react-three/drei';

export const RotatingCubePop: React.FC<{
  cubeColor?: string;
  backgroundColor?: string;
  rotationSpeed?: number;
  cubeSize?: number;
  edgeThickness?: number;
  particleCount?: number;
  particleSeed?: string;
}> = ({
  cubeColor = '#FFD700',
  backgroundColor = '#000000',
  rotationSpeed = 0.5,
  cubeSize = 100,
  edgeThickness = 4,
  particleCount = 20,
  particleSeed = 'cube-pop-particles',
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  return (
    <AbsoluteFill style={{ backgroundColor }}>
      <ThreeCanvas
        width={width}
        height={height}
        camera={{ fov: 75, position: [0, 0, 470] }}
      >
        <ambientLight intensity={0.5} />
        <AnimatedCube
          frame={frame}
          fps={fps}
          cubeColor={cubeColor}
          cubeSize={cubeSize}
          edgeThickness={edgeThickness}
          rotationSpeed={rotationSpeed}
        />
        <ParticleField
          frame={frame}
          fps={fps}
          particleCount={particleCount}
          particleSeed={particleSeed}
          particleColor={cubeColor}
        />
      </ThreeCanvas>
    </AbsoluteFill>
  );
};

