const AnimatedCube: React.FC<{
  frame: number;
  fps: number;
  cubeColor: string;
  cubeSize: number;
  edgeThickness: number;
  rotationSpeed: number;
}> = ({ frame, fps, cubeColor, cubeSize, edgeThickness, rotationSpeed }) => {
  // Rotation: continuous, frame-rate-independent
  const rotationY = (frame / fps) * Math.PI * rotationSpeed;

  // Scale: two-phase animation
  const scalePhase1 = interpolate(frame, [0, 60], [0.3, 1.5], {
    easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const scalePhase2 = interpolate(frame, [60, 72], [1.5, 2.8], {
    easing: Easing.bezier(0.68, -0.55, 0.265, 1.55),
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const scale = frame < 60 ? scalePhase1 : scalePhase2;

  // Opacity: fade out during pop
  const opacity = interpolate(frame, [60, 72], [1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  // Don't render if fully transparent
  if (opacity <= 0) return null;

  return (
    <mesh rotation={[0, rotationY, 0]} scale={scale}>
      <boxGeometry args={[cubeSize, cubeSize, cubeSize]} />
      <meshBasicMaterial transparent opacity={0} />
      <Edges
        color={cubeColor}
        lineWidth={edgeThickness}
        threshold={15}
      />
    </mesh>
  );
};

