const ParticleField: React.FC<{
  frame: number;
  fps: number;
  particleCount: number;
  particleSeed: string;
  particleColor: string;
}> = ({ frame, fps, particleCount, particleSeed, particleColor }) => {
  // Don't render before explosion starts
  if (frame < 70) return null;

  // Generate deterministic particle data - MEMOIZED
  const particles = useMemo(() => {
    return Array.from({ length: particleCount }, (_, i) => {
      // Normalize direction vector for even distribution
      const dirX = random(`${particleSeed}-dir-x-${i}`) * 2 - 1;
      const dirY = random(`${particleSeed}-dir-y-${i}`) * 2 - 1;
      const dirZ = random(`${particleSeed}-dir-z-${i}`) * 2 - 1;
      const mag = Math.sqrt(dirX * dirX + dirY * dirY + dirZ * dirZ);

      return {
        id: i,
        dirX: dirX / mag,
        dirY: dirY / mag,
        dirZ: dirZ / mag,
        speed: random(`${particleSeed}-speed-${i}`) * 200 + 100,
        size: random(`${particleSeed}-size-${i}`) * 8 + 4,
      };
    });
  }, [particleCount, particleSeed]);

  // Animation progress
  const explosionProgress = interpolate(frame, [70, 90], [0, 1], {
    easing: Easing.bezier(0.0, 0.0, 0.2, 1.0),
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const particleOpacity = interpolate(frame, [70, 75, 90], [0, 1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  return (
    <group>
      {particles.map((p) => {
        const x = p.dirX * p.speed * explosionProgress;
        const y = p.dirY * p.speed * explosionProgress;
        const z = p.dirZ * p.speed * explosionProgress;

        return (
          <mesh key={p.id} position={[x, y, z]}>
            <sphereGeometry args={[p.size, 8, 8]} />
            <meshBasicMaterial
              color={particleColor}
              transparent
              opacity={particleOpacity}
            />
          </mesh>
        );
      })}
    </group>
  );
};
